-- mod-lan: Zul'Farrak for the adventure route. Every mob in Zul'Farrak drops an Executioner's Key (8444) for players
-- who don't have one, not only the single Sandfury Executioner (his own drop stays as it is). The key opens the
-- troll cages for the pyramid event before Chief Ukorz Sandscalp.
-- The loot ids are those of the creatures spawned on map 209, without the Executioner's own (7274); the map
-- condition keeps the drop inside Zul'Farrak for creatures that also stand elsewhere.

DELETE FROM `creature_loot_template` WHERE `Item` = 8444 AND `Entry` IN (5648, 5649, 5650, 7246, 7247, 7267, 7268, 7269, 7271, 7272, 7604, 7605, 7606, 7607, 7608, 7795, 7797, 8095, 8120, 8127, 10080, 10081, 10082);

DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId` = 1 AND `SourceEntry` = 8444 AND `SourceGroup` IN (5648, 5649, 5650, 7246, 7247, 7267, 7268, 7269, 7271, 7272, 7604, 7605, 7606, 7607, 7608, 7795, 7797, 8095, 8120, 8127, 10080, 10081, 10082);
